import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Developer Summit Quincy- CI","description":"","frontmatter":{"title":"Ceph Developer Summit Quincy- CI","date":"2021-04-12T00:00:00.000Z","updated":"2021-04-13T00:00:00.000Z","tags":["Ceph","CI/CD","测试基础设施","Jenkins","Cephadm"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_CI.md","filePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_CI.md","lastUpdated":1780459816000}'),n={name:"posts/2021/Ceph_Developer_Summit_Quincy_-_CI.md"};function o(r,l,s,h,u,p){return e(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-测试基础设施改进讨论" tabindex="-1">会议主题：测试基础设施改进讨论 <a class="header-anchor" href="#会议主题-测试基础设施改进讨论" aria-label="Permalink to &quot;会议主题：测试基础设施改进讨论&quot;">​</a></h4><h4 id="参会人员-david-galloway等" tabindex="-1">参会人员：David Galloway等 <a class="header-anchor" href="#参会人员-david-galloway等" aria-label="Permalink to &quot;参会人员：David Galloway等&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Jenkins作业和构建器的可靠性改进</strong>：</p><ul><li>讨论了Jenkins作业中存在的竞争条件问题，建议增加详细日志记录并延长日志存储时间。</li><li>提出了设置预生产环境，以便在实际部署前更广泛地测试更改。</li></ul></li><li><p><strong>测试环境的改进</strong>：</p><ul><li>讨论了如何改进测试节点升级或添加新补丁包时的现有设置。</li><li>提出了使用临时Jenkins实例进行更详细的测试。</li></ul></li><li><p><strong>PR标签和优先级</strong>：</p><ul><li>讨论了如何标记对构建器测试设置修复重要的PR，以便更容易识别和优先审查。</li></ul></li><li><p><strong>日志和调试改进</strong>：</p><ul><li>讨论了如何改进Jenkins日志，使其更易于调试，特别是在make check测试中。</li><li>提出了使用CTest输出机器可读信息，以便更容易识别失败的单个测试。</li></ul></li><li><p><strong>元数据和机器信息</strong>：</p><ul><li>讨论了在Jenkins作业中包含更多关于运行作业的机器的元数据，以便更好地识别特定发行版或机器类型上的问题。</li></ul></li><li><p><strong>已知竞争条件的处理</strong>：</p><ul><li>讨论了如何处理已知的难以调试的竞争条件，建议Jenkins能够自动重新运行遇到已知问题的作业。</li></ul></li><li><p><strong>集成测试和Cephadm的改进</strong>：</p><ul><li>讨论了如何改进集成测试，特别是通过Cephadm部署和管理集群的能力。</li><li>提出了增加更多工具和框架，如CBT，以收集更多运行时的资源利用信息。</li></ul></li><li><p><strong>容器构建过程的改进</strong>：</p><ul><li>讨论了容器构建过程的脆弱性，建议将Dockerfile移到Ceph树中，以简化容器构建过程。</li></ul></li><li><p><strong>降级测试</strong>：</p><ul><li>讨论了降级测试的重要性，建议创建一个专门的降级测试套件。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>增加Jenkins作业的日志详细程度和存储时间。</li><li>设置预生产环境以测试基础设施更改。</li><li>标记和优先处理对构建器测试设置修复重要的PR。</li><li>改进Jenkins日志以更易于调试。</li><li>在Jenkins作业中包含更多机器元数据。</li><li>自动重新运行遇到已知竞争条件的Jenkins作业。</li><li>改进Cephadm以支持更复杂的部署和管理任务。</li><li>简化容器构建过程。</li><li>创建降级测试套件。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>实施日志改进措施。</li><li>设置和配置预生产环境。</li><li>开发和部署PR标签和优先级系统。</li><li>改进Jenkins日志和调试工具。</li><li>实施机器元数据收集。</li><li>开发自动重新运行Jenkins作业的机制。</li><li>改进Cephadm以支持更多集成测试。</li><li>简化容器构建过程。</li><li>创建和实施降级测试套件。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的具体技术和工具，如Jenkins, Cephadm, CTest, CBT等，是Ceph分布式存储系统开发和测试中的关键组件。</li><li>会议讨论了多个技术细节和改进措施，旨在提高测试基础设施的可靠性和效率，确保Ceph系统的稳定性和性能。</li></ul>',13)])])}const _=i(n,[["render",o]]);export{c as __pageData,_ as default};
